// Wave GEN lane B — SPEC G20-G39: the stat morph (StatMorph.ts), its inflate/carve sculpt (Physique.ts),
// the race posture curves (SpineCurve.ts) and the race digit distribution (Hands.ts / HandRig.ts).
// Numbers of record live in docs/wave-gen/ANATOMY.md (generated by tools/measure-wave-gen-anatomy.ts).

import { anatomyFor, pairDeviations } from "../src/graphics/body/Anatomy.ts";
import { generateBody, skinField } from "../src/graphics/body/BodyMesh.ts";
import { LANDMARK_CARVE, measureMorph, type MorphMeasure } from "../src/graphics/body/Physique.ts";
import {
  DIGITS_NEUTRAL, gainTerm, isStatIdentity, MUSCLE_GROUPS, morphBounds, morphScalars, normaliseStat, RACE_DIGITS, STAT_MAX, STAT_MIN,
  STAT_REFERENCE, statMorph,
} from "../src/graphics/body/StatMorph.ts";
import { ERECT_POSTURE, POSTURE_BOUNDS, postureCurve, RACE_POSTURE, raceSpineColumn, spineColumn } from "../src/game/SpineCurve.ts";
import { handSize } from "../src/graphics/body/Hands.ts";
import type { BodySpec, GeneratorStats } from "../src/graphics/body/contracts.ts";
import { BODIES, meshVolume, specOf } from "../tools/measure-wave-gen-anatomy.ts";

function assert(ok: unknown, msg = "assertion failed"): asserts ok { if (!ok) throw new Error(msg); }
function assertEquals(a: unknown, b: unknown, msg = ""): void {
  const ja = JSON.stringify(a), jb = JSON.stringify(b);
  if (ja !== jb) throw new Error(`${msg}: ${String(ja).slice(0, 200)} !== ${String(jb).slice(0, 200)}`);
}

const RACES = ["human", "elf", "dwarf", "ork"] as const;
const S = { d: 0, region: 0, bone: 0 };
const measure = (spec: BodySpec, opts?: Parameters<typeof anatomyFor>[1]): { m: MorphMeasure; plan: ReturnType<typeof anatomyFor> } => {
  const plan = anatomyFor(spec, opts);
  const f = skinField(plan);
  return { m: measureMorph((x, y, z) => f.sample(x, y, z, S).d, plan), plan };
};
const stats = (p: Partial<GeneratorStats>): GeneratorStats => ({ ...STAT_REFERENCE, ...p });

Deno.test("SPEC G20: the morph is the identity at STAT_REFERENCE and for absent stats", () => {
  for (const race of RACES) for (const sex of ["male", "female"] as const) {
    const a = statMorph(STAT_REFERENCE, race, null, sex), b = statMorph(null, race, null, sex);
    assert(a.statIdentity && b.statIdentity, `${race}/${sex}`);
    assertEquals(morphScalars(a), morphScalars(b));
    for (const v of Object.entries(morphScalars(a))) assertEquals(v[1], v[0].endsWith("Mm") || v[0].endsWith("PerHead") ? 0 : 1, v[0]);
  }
  assertEquals(normaliseStat(500, 500), 0);
  assertEquals(normaliseStat(STAT_MIN, 500), -1);
  assertEquals(normaliseStat(STAT_MAX, 500), 1);
});

Deno.test("SPEC G21: every term is monotone non-decreasing in its own stat and blind to the others", () => {
  const owner: Record<string, keyof GeneratorStats> = { boneDensity: "strength", shoulderBreadth: "strength", "maturity.mass": "level", "maturity.liftPerHead": "level", browRecessMm: "intelligence" };
  for (const g of MUSCLE_GROUPS) owner[`muscle.${g}`] = "strength";
  for (const sex of ["male", "female"] as const) for (const stat of ["strength", "agility", "intelligence", "level"] as const) {
    let prev: Record<string, number> | null = null;
    for (let v = -100; v <= 1100; v += 25) {
      const cur = morphScalars(statMorph(stats({ [stat]: v }), "human", null, sex));
      if (prev) {
        for (const [k, x] of Object.entries(cur)) {
          if (owner[k] === stat) assert(x >= prev[k] - 1e-12, `${k} falls with ${stat} at ${v}`);
          else assertEquals(x, prev[k], `${k} moved with ${stat}`);
        }
      }
      prev = cur;
    }
  }
  // Strictly increasing where it matters (a real slope both sides of the reference).
  const lo = statMorph(stats({ strength: 0 }), "ork", null, "male"), hi = statMorph(stats({ strength: 1000 }), "ork", null, "male");
  for (const g of MUSCLE_GROUPS) assert(lo.muscle[g] < 1 && hi.muscle[g] > 1, g);
});

Deno.test("SPEC G22: every term stays inside its bound for any input (out of range, NaN, Infinity)", () => {
  const B = morphBounds();
  const vals = [-1e9, -1, 0, 1, 250, 499.999, 500, 500.001, 750, 999, 1000, 1001, 1e9, Number.NaN, Number.POSITIVE_INFINITY];
  for (const sex of ["male", "female", null] as const) for (const s of vals) for (const i of vals) for (const l of [0, 500, 1000, Number.NaN]) {
    const m = morphScalars(statMorph({ strength: s, agility: 500, intelligence: i, level: l }, "dwarf", null, sex));
    for (const [k, v] of Object.entries(m)) {
      assert(Number.isFinite(v), `${k} not finite`);
      assert(v >= B[k][0] - 1e-12 && v <= B[k][1] + 1e-12, `${k} = ${v} outside ${B[k]}`);
    }
  }
  assertEquals(gainTerm(0, { up: 1, down: 1 }), 1);
  for (const r of Object.keys(RACE_POSTURE)) {
    const p = postureCurve(r, "ironhide");
    assert(p.neckForwardPerHead <= POSTURE_BOUNDS.neckForwardPerHead[1] && p.lumbarDepthPerHead <= POSTURE_BOUNDS.lumbarDepthPerHead[1] && p.trapezius <= POSTURE_BOUNDS.trapezius[1]);
  }
});

Deno.test("SPEC G23: the sculpted skin stays mirror-symmetric under the morph (no side term)", () => {
  for (const race of ["human", "ork"] as const) for (const st of [0, 1000]) {
    const plan = anatomyFor(specOf(race, "male", { strength: st, intelligence: 1000 - st, level: st }), { asymmetry: false });
    const devs = pairDeviations(plan.skinRoot);
    const worst = Math.max(...devs.map((d) => d.dev));
    assert(devs.length > 30, `${race}: ${devs.length} pairs`);
    assert(worst <= 1e-9, `${race} str ${st}: L/R deviation ${worst} (${devs.find((d) => d.dev === worst)?.id})`);
  }
});

Deno.test("SPEC G24: stats at STAT_REFERENCE build the very same body as absent stats (every race)", () => {
  for (const race of RACES) {
    const a = anatomyFor(specOf(race, "male", {})), b = anatomyFor(specOf(race, "male", null));
    assertEquals(JSON.stringify([a.root, a.skinRoot, a.skinInflated, a.bones, a.bounds, a.skinBounds, a.face, a.strokes]),
      JSON.stringify([b.root, b.skinRoot, b.skinInflated, b.bones, b.bounds, b.skinBounds, b.face, b.strokes]), race);
    // Human/elf at the reference: no hit tree (capsules exactly as today); ork/dwarf: the race posture's.
    assertEquals(a.hitRoot === undefined, race === "human" || race === "elf", `${race} hitRoot`);
    assertEquals(JSON.stringify(a.hitRoot), JSON.stringify(b.hitRoot), `${race} hitRoot ref == absent`);
  }
});

Deno.test("SPEC G25: the physics body (root, bones, bounds, abductions) is byte-identical for every stat", () => {
  for (const race of RACES) {
    const key = (p: ReturnType<typeof anatomyFor>) => JSON.stringify([p.root, p.bones, p.bounds, p.armAbduction, p.legAbduction, p.armDisplayAbduction, p.cell]);
    const ref = key(anatomyFor(specOf(race, "female", null)));
    for (const s of [stats({ strength: 0 }), stats({ strength: 1000, level: 1000, intelligence: 0 }), stats({ intelligence: 1000, level: 0 })]) {
      assertEquals(key(anatomyFor({ ...specOf(race, "female", null), stats: s })), ref, `${race} ${JSON.stringify(s)}`);
    }
  }
});

Deno.test("SPEC G26: hitRoot carries the stat terms and the race posture; its box grows by whole cells on the physics grid", () => {
  const plan = anatomyFor(specOf("human", "male", { strength: 1000 }));
  assert(plan.hitRoot && plan.hitBounds);
  const c = plan.cell;
  for (let k = 0; k < 3; k++) {
    if (k === 2) continue; // z is padded from the raw extent, not a grid axis of the phase pins
    const dmin = (plan.bounds.min[k] - plan.hitBounds.min[k]) / c, dmax = (plan.hitBounds.max[k] - plan.bounds.max[k]) / c;
    assert(dmin >= -1e-9 && Math.abs(dmin - Math.round(dmin)) < 1e-6, `axis ${k} min ${dmin}`);
    assert(dmax >= -1e-9 && Math.abs(dmax - Math.round(dmax)) < 1e-6, `axis ${k} max ${dmax}`);
  }
  // The race posture IS in the hit tree (Q1 Z-38): the ork's hit head moves with the rendered head,
  // by exactly the posture offset; the physics head (root, ragdoll) stays where it was.
  const ork = anatomyFor(specOf("ork", "male", null));
  const find = (n: unknown, id: string): { a: number[] } | null => {
    const q = n as { type: string; primitive?: { id: string; a: number[] }; children?: unknown[] };
    if (q.type === "primitive") return q.primitive!.id === id ? q.primitive! : null;
    for (const c of q.children!) { const f = find(c, id); if (f) return f; }
    return null;
  };
  const off = ork.morph.posture.neckForwardPerHead * ork.proportions.head;
  assert(Math.abs(find(ork.hitRoot, "cranium")!.a[2] - find(ork.root, "cranium")!.a[2] - off) < 1e-12, "hit head follows the posture");
  assert(Math.abs(find(ork.skinRoot, "cranium")!.a[2] - find(ork.hitRoot, "cranium")!.a[2]) < 1e-12, "hit head == rendered head");
});

Deno.test("SPEC G27: muscle girths, chest, back (lats), trapezius and shoulder breadth grow with strength", () => {
  for (const [race, sex] of [["human", "male"], ["ork", "female"], ["elf", "male"]] as const) {
    const ms = [0, 500, 1000].map((st) => measure(specOf(race, sex, { strength: st })).m);
    for (const k of ["bicepsGirth", "quadricepsGirth", "calfGirth", "pectoralFrontZ", "shoulderBreadth"] as const) {
      assert(ms[0][k] < ms[1][k] && ms[1][k] < ms[2][k], `${race}/${sex} ${k}: ${ms.map((m) => m[k].toFixed(4))}`);
    }
    // The flank and the slope barely move below the reference (the lats/trapezius shrink into the trunk): within 1 mm.
    for (const k of ["trapeziusTopY"] as const) assert(ms[0][k] <= ms[1][k] + 0.001 && ms[1][k] < ms[2][k], `${race}/${sex} ${k}: ${ms.map((m) => m[k].toFixed(4))}`);
    // The lats thicken the back behind the arm's plane (more negative z = thicker), >= 8 mm at max.
    assert(ms[0].latBackZ >= ms[1].latBackZ - 0.001 && ms[2].latBackZ < ms[1].latBackZ - 0.008, `${race}/${sex} latBackZ: ${ms.map((m) => m.latBackZ.toFixed(4))}`);
    // Biceps at max strength: +20 % or more (bounded by the 32 % gain of its belly).
    assert(ms[2].bicepsGirth / ms[1].bicepsGirth > 1.1 && ms[2].bicepsGirth / ms[1].bicepsGirth < 1.5, `${race} biceps ratio`);
  }
});

Deno.test("SPEC G28: carved landmarks stay readable on the inflated body (max strength >= reference)", () => {
  for (const race of RACES) {
    const ref = measure(specOf(race, "male", null)).m, max = measure(specOf(race, "male", { strength: 1000 })).m;
    for (const k of ["clavicleValley", "sternalGroove", "kneecapProud", "iliacGroove"] as const) {
      assert(max[k] >= ref[k] - 0.0005, `${race} ${k}: ref ${(ref[k] * 1000).toFixed(1)} mm -> max ${(max[k] * 1000).toFixed(1)} mm`);
    }
    // Every landmark has a real, visible depth at max strength (>= 2 mm).
    for (const k of ["clavicleValley", "sternalGroove", "kneecapProud", "iliacGroove"] as const) assert(max[k] >= 0.002, `${race} ${k} = ${max[k]}`);
  }
  assert(LANDMARK_CARVE.kneecap.depthPerHead > 0);
});

Deno.test("SPEC G29: intelligence recesses the brow ridge by the stated millimetres (measured on the field)", () => {
  for (const race of ["human", "dwarf"] as const) {
    const z = [0, 500, 1000].map((iq) => measure(specOf(race, "male", { intelligence: iq })));
    const d = z.map((r) => r.m.browFrontZ);
    assert(d[0] > d[1] && d[1] > d[2], `${race}: brow front ${d}`);
    const span = (d[0] - d[2]) * 1000, stated = z[2].plan.morph.browRecessMm - z[0].plan.morph.browRecessMm;
    assert(Math.abs(span - stated) < 1.5, `${race}: measured ${span.toFixed(2)} mm vs stated ${stated} mm`);
    // The brow anchors (eyebrow parts) follow the ridge exactly.
    assert(Math.abs((z[0].plan.face.brow[0][2] - z[2].plan.face.brow[0][2]) * 1000 - stated) < 1e-6);
  }
});

Deno.test("SPEC G30: level's maturity term is small and bounded; the height term is fixed at 1", () => {
  for (const race of ["human", "ork"] as const) {
    const lo = measure(specOf(race, "male", { level: 0 })), hi = measure(specOf(race, "male", { level: 1000 })), ref = measure(specOf(race, "male", null));
    assert(lo.m.pectoralFrontZ < ref.m.pectoralFrontZ && ref.m.pectoralFrontZ < hi.m.pectoralFrontZ);
    assert(hi.m.pectoralFrontZ - ref.m.pectoralFrontZ < 0.04 * ref.plan.proportions.head, "the chest lift stays a gravitas term");
    assertEquals(hi.plan.morph.maturity.height, 1);
    assertEquals(hi.plan.bones, ref.plan.bones);
  }
});

Deno.test("SPEC G31: posture curves — ork head forward on a heavier trapezius, dwarf lumbar hollow, human/elf erect", () => {
  assertEquals(postureCurve("human"), ERECT_POSTURE);
  assertEquals(postureCurve("elf", "high"), ERECT_POSTURE);
  const erect = (_race: string) => ({ physique: { morph: statMorph(null, "human", null, "male") } });
  const ork = measure(specOf("ork", "male", null)), orkE = measure(specOf("ork", "male", null), erect("ork"));
  const h = ork.plan.proportions.head;
  const fwd = ork.m.headForward - orkE.m.headForward;
  assert(fwd > 0.08 * h && fwd < 0.2 * h, `ork head forward ${(fwd * 1000).toFixed(1)} mm (${(fwd / h).toFixed(3)} h)`);
  assert(ork.m.trapeziusTopY > orkE.m.trapeziusTopY, "ork trapezius rises");
  const dw = measure(specOf("dwarf", "male", null)), dwE = measure(specOf("dwarf", "male", null), erect("dwarf"));
  const lum = dw.m.lumbarDepth - dwE.m.lumbarDepth;
  assert(lum > 0.02 * dw.plan.proportions.head, `dwarf lumbar +${(lum * 1000).toFixed(1)} mm`);
  for (const race of ["human", "elf"] as const) {
    const a = anatomyFor(specOf(race, "male", null)), b = anatomyFor(specOf(race, "male", null), erect(race));
    assertEquals(JSON.stringify(a.skinRoot), JSON.stringify(b.skinRoot), `${race} is erect: no posture sculpt`);
  }
});

Deno.test("SPEC G32: the race spine columns scale the canonical curves (human/elf = the canon)", () => {
  assertEquals(raceSpineColumn("human"), spineColumn());
  assertEquals(raceSpineColumn("elf", "wood"), spineColumn());
  const amp = (race: string, curve: string) => Math.max(...raceSpineColumn(race).filter((v) => v.curve === curve).map((v) => Math.abs(v.z)));
  assert(amp("ork", "cervical") > amp("human", "cervical"));
  assert(amp("dwarf", "lumbar") > amp("human", "lumbar"));
  assertEquals(raceSpineColumn("ork").length, 33);
});

Deno.test("SPEC G33: the face anchors follow the rendered head (ork forward neck); bones do not move", () => {
  const ork = anatomyFor(specOf("ork", "male", null)), orkE = anatomyFor(specOf("ork", "male", null), { physique: { morph: statMorph(null, "human", null, "male") } });
  const off = ork.morph.posture.neckForwardPerHead * ork.proportions.head;
  for (let k = 0; k < 2; k++) assert(Math.abs(ork.face.eye[k][2] - orkE.face.eye[k][2] - off) < 1e-12);
  assertEquals(ork.face.skullRadii, orkE.face.skullRadii);
  assertEquals(ork.bones, orkE.bones);
});

Deno.test("SPEC G34: race digit distribution — elf slender/long ... ork thickest knuckles, broadest palm", () => {
  const inp = { hand: 0.19, palmHalfWidth: 0.045, palmHalfThickness: 0.015, wrist: 0.03, thumb: 1 as const };
  const hs = Object.fromEntries(RACES.map((r) => [r, handSize({ ...inp, digits: RACE_DIGITS[r] })]));
  const len = (r: string) => hs[r].phalanx[1][0] + hs[r].phalanx[1][1] + hs[r].phalanx[1][2];
  const knuckle = (r: string) => hs[r].fingerR[1] * (hs[r].knuckleK ?? 1);
  assert(len("elf") > len("human") && len("human") >= len("dwarf") && len("dwarf") > len("ork"), "finger length order");
  assert(hs.elf.fingerR[1] < hs.human.fingerR[1] && hs.human.fingerR[1] < hs.dwarf.fingerR[1] && hs.dwarf.fingerR[1] < hs.ork.fingerR[1], "finger radius order");
  assert(knuckle("ork") > knuckle("dwarf") && knuckle("dwarf") > knuckle("human") && knuckle("human") > knuckle("elf"), "knuckle order");
  assert(hs.ork.halfW > hs.dwarf.halfW && hs.dwarf.halfW > hs.human.halfW && hs.human.halfW > hs.elf.halfW, "palm order");
  const slender = (r: string) => len(r) / hs[r].fingerR[1];
  assert(slender("elf") > slender("human") && slender("human") > slender("dwarf") && slender("dwarf") > slender("ork"), "slenderness elf > human > dwarf > ork");
});

Deno.test("SPEC G35: absent digits = the neutral (pre-wave) hand exactly; the rig passes the plan's digits", () => {
  const inp = { hand: 0.19, palmHalfWidth: 0.045, palmHalfThickness: 0.015, wrist: 0.03, thumb: -1 as const };
  assertEquals(handSize(inp), handSize({ ...inp, digits: DIGITS_NEUTRAL }));
  assertEquals(RACE_DIGITS.human, DIGITS_NEUTRAL);
  assertEquals(anatomyFor(specOf("ork", "male", null)).morph.digits, RACE_DIGITS.ork);
});

Deno.test("SPEC G36: the morphed skin is one closed manifold within the triangle budget (4 races, min/max strength)", () => {
  const refTris = Object.fromEntries(RACES.map((r) => [r, generateBody(specOf(r, "female", null)).stats.triangles]));
  for (const race of RACES) for (const [sex, st] of [["male", 0], ["male", 1000], ["female", 1000]] as const) {
    const b = generateBody(specOf(race, sex, { strength: st, level: st, intelligence: st }));
    const s = b.stats;
    assertEquals([s.boundaryEdges, s.nonManifoldEdges], [0, 0], `${race}/${sex}/${st}`);
    // elf/high carries a pre-existing pair of brow-tip islands (Q1 baseline, HEAD): allow them, nothing new.
    assert(s.components <= (race === "elf" ? 3 : 1), `${race}/${sex}/${st}: ${s.components} components`);
    assert(s.triangles < 12000, `${race}/${sex}/${st}: ${s.triangles} triangles`);
    // The skin's own cell (Anatomy.skinCell) keeps a strong body near the reference's triangle count.
    if (sex === "female") assert(s.triangles <= 1.04 * refTris[race], `${race}/${sex}/${st}: ${s.triangles} vs ref ${refTris[race]}`);
    const sc = (b.plan as { skinCell?: number }).skinCell;
    if (sc !== undefined) assert(sc >= b.plan.cell && sc <= 1.12 * b.plan.cell + 1e-12, `${race}: skinCell ${sc} vs cell ${b.plan.cell}`);
  }
});

Deno.test("SPEC G37: body volume (mass at constant density) rises with strength, bounded", () => {
  for (const race of ["human", "dwarf"] as const) {
    const v = [0, 500, 1000].map((st) => meshVolume(generateBody(specOf(race, "male", { strength: st })).mesh));
    assert(v[0] < v[1] && v[1] < v[2], `${race}: ${v}`);
    assert(v[2] / v[1] < 1.15 && v[0] / v[1] > 0.9, `${race}: mass change ${(v[2] / v[1]).toFixed(3)} / ${(v[0] / v[1]).toFixed(3)}`);
  }
});

Deno.test("SPEC G38: the morph reaches the physics only through hitRoot (absent for an identity morph)", () => {
  for (const race of RACES) {
    assertEquals(anatomyFor(specOf(race, "male", null)).hitRoot === undefined, race === "human" || race === "elf", race);
    assert(anatomyFor(specOf(race, "male", { strength: 0 })).hitRoot);
    // intelligence alone is a face term only: no hit tree
    const iq = anatomyFor(specOf(race, "male", { intelligence: 1000 }));
    assert(iq.hitRoot, "intelligence moves the brow, a stat term -> hit tree present (brow excluded from it)");
    assert(!isStatIdentity(iq.morph));
  }
});

Deno.test("SPEC G39: docs/wave-gen/ANATOMY.md tables are generated from artifacts/wave-gen/anatomy/measure.json", async () => {
  const doc = await Deno.readTextFile("docs/wave-gen/ANATOMY.md");
  assert(doc.includes("<!-- GENERATED:BEGIN tools/measure-wave-gen-anatomy.ts -->") && doc.includes("<!-- GENERATED:END -->"));
  const data = JSON.parse(await Deno.readTextFile("artifacts/wave-gen/anatomy/measure.json"));
  assertEquals(data.strength.length, 4 * 2 * 3);
  assertEquals(Object.keys(data.bodies), Object.keys(BODIES));
  for (const r of data.strength) {
    assert(r.physicsIdentical, `${r.race}/${r.sex}/${r.strength}: physics moved`);
    assertEquals([r.boundaryEdges, r.nonManifoldEdges], [0, 0]);
    // the first row's numbers appear in the doc verbatim (no hand-typed table)
  }
  const r0 = data.strength[0];
  assert(doc.includes(`| ${r0.race} | ${r0.sex} | ${r0.strength} | ${(Math.round(r0.bicepsGirth * 10000) / 10).toFixed(1)} |`));
});
